    rows = {}
    for r, c in points:
        rows.setdefault(r, []).append(c)
    spine_row = max(rows, key=lambda r: len(rows[r]))
    spine_cols = rows[spine_row]
    if len(spine_cols) < 2:
        return out
    for c in range(min(spine_cols), max(spine_cols) + 1):
        if out[spine_row][c] == 0:
            out[spine_row][c] = 3
    for r, c in points:
        if r == spine_row:
            continue
        for rr in range(min(r, spine_row), max(r, spine_row) + 1):
            if out[rr][c] == 0:
                out[rr][c] = 3
    return out
