 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    row_counts = {}
    col_counts = {}
    for r, c in points:
        row_counts[r] = row_counts.get(r, 0) + 1
        col_counts[c] = col_counts.get(c, 0) + 1
    shared_rows = [r for r, n in row_counts.items() if n >= 2]
    shared_cols = [c for c, n in col_counts.items() if n >= 2]
    # Use the line on which multiple markers are aligned as the backbone.
    if shared_rows:
        r0 = shared_rows[0]
        cols = [c for r, c in points if r == r0]
        for c in range(min(cols), max(cols) + 1):
            if out[r0][c] == 0:
                out[r0][c] = 3
        for r, c in points:
            if r != r0:
                for rr in range(min(r, r0), max(r, r0) + 1):
                    if out[rr][c] == 0:
                        out[rr][c] = 3
    elif shared_cols:
        c0 = shared_cols[0]
        rows = [r for r, c in points if c == c0]
        for r in range(min(rows), max(rows) + 1):
            if out[r][c0] == 0:
                out[r][c0] = 3
        for r, c in points:
            if c != c0:
                for cc in range(min(c, c0), max(c, c0) + 1):
                    if out[r][cc] == 0:
                        out[r][cc] = 3
    return out
